    font-size: 0.875rem;
}

.review-section-header a:hover {
    text-decoration: underline;
}

.review-details p {
    margin: 0.25rem 0;
    color: #495057;
}

.review-work-entry,
.review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #eee;
}

.review-work-entry:last-child,
.review-reference:last-child {
    border-bottom: none;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
