+    border-color: #86b7fe;
+    outline: 0;
+    box-shadow: 0 0 0 0.2rem rgba(13, 110, 253, 0.25);
+}
+
+.form-control:disabled {
+    background-color: #e9ecef;
+}
+
+textarea.form-control {
+    resize: vertical;
+}
+
+.form-row {
+    display: flex;
+    gap: 1rem;
+    flex-wrap: wrap;
+}
+
+.form-row .form-group {
+    flex: 1;
+    min-width: 150px;
+}
+
+.form-check-group {
+    display: flex;
+    align-items: flex-end;
+    padding-bottom: 0.5rem;
+}
+
+.form-check-group label {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    cursor: pointer;
+    font-weight: normal;
+}
+
+/* Buttons */
+.form-buttons {
+    display: flex;
+    justify-content: space-between;
+    margin-top: 2rem;
+    padding-top: 1rem;
+    border-top: 1px solid #dee2e6;
+}
+
+.btn {
+    padding: 0.5rem 1.5rem;
+    font-size: 1rem;
+    border-radius: 4px;
+    cursor: pointer;
+    border: 1px solid transparent;
+    transition: all 0.15s ease-in-out;
+}
+
+.btn:disabled {
+    opacity: 0.65;
+    cursor: not-allowed;
+}
+
+.btn-primary {
+    background: #0d6efd;
+    color: #fff;
+    border-color: #0d6efd;
+}
+
+.btn-primary:hover:not(:disabled) {
+    background: #0b5ed7;
+    border-color: #0a58ca;
+}
+
+.btn-outline {
+    background: #fff;
+    color: #6c757d;
+    border-color: #6c757d;
+}
+
+.btn-outline:hover {
+    background: #6c757d;
+    color: #fff;
+}
+
+.btn-secondary {
+    background: #6c757d;
+    color: #fff;
+    border-color: #6c757d;
+}
+
+.btn-secondary:hover {
+    background: #5c636a;
+}
+
+.btn-danger {
+    background: #dc3545;
+    color: #fff;
+    border-color: #dc3545;
+}
+
+.btn-danger:hover {
+    background: #bb2d3b;
+}
+
+.btn-sm {
+    padding: 0.25rem 0.75rem;
+    font-size: 0.875rem;
+}
+
+.btn-submit {
+    padding: 0.75rem 2rem;
+    font-size: 1.1rem;
+}
+
+/* Alert */
+.alert {
+    padding: 0.75rem 1rem;
+    border-radius: 4px;
+    margin-bottom: 1rem;
+}
+
+.alert-danger {
+    background: #f8d7da;
+    color: #842029;
+    border: 1px solid #f5c2c7;
+}
+
+/* Work Entry & Reference Cards */
+.work-entry-card,
+.reference-card {
+    border: 1px solid #dee2e6;
+    border-radius: 6px;
+    padding: 1.5rem;
+    margin-bottom: 1rem;
+    background: #f8f9fa;
+}
+
+.work-entry-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 1rem;
+}
+
+.work-entry-header h4 {
+    margin: 0;
+    color: #495057;
+}
+
+/* Cover Letter */
+.cover-letter-textarea {
+    min-height: 250px;
+}
+
+.character-count {
+    text-align: right;
+    font-size: 0.875rem;
+    color: #6c757d;
+    margin-top: 0.25rem;
+}
+
+/* Review Section */
+.review-section {
+    border: 1px solid #dee2e6;
+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+}
+
+.review-section-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+.review-section-header h3 {
+    margin: 0;
+    font-size: 1.1rem;
+    color: #212529;
+}
+
+.review-section-header a {
+    color: #0d6efd;
+    text-decoration: none;
+    font-size: 0.875rem;
+}
+
+.review-section-header a:hover {
+    text-decoration: underline;
+}
+
+.review-details p {
+    margin: 0.25rem 0;
+    color: #495057;
+}
+
+.review-work-entry,
+.review-reference {
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #eee;
+}
+
+.review-work-entry:last-child,
+.review-reference:last-child {
+    border-bottom: none;
+}
+
+.cover-letter-preview {
+    white-space: pre-wrap;
+    background: #f8f9fa;
+    padding: 1rem;
+    border-radius: 4px;
+    max-height: 200px;
+    overflow-y: auto;
+}
+
+/* Submission Confirmation */
+.submission-confirmation {
+    text-align: center;
+    padding: 3rem 1rem;
+}
+
+.submission-confirmation h2 {
+    color: #198754;
+    font-size: 1.75rem;
+}
+
+.submission-confirmation p {
+    font-size: 1.1rem;
+    color: #495057;
+}
+

